return {
    commify = function(_, p2) -- commify | line: 1
        assert(type(p2) == "number", "Attempt to commify a non-number value")

        local v2 = tostring(p2)

        repeat
            local v3

            v2, v3 = string.gsub(v2, "^(-?%d+)(%d%d%d)", "%1,%2")
        until v3 == 0

        return v2
    end
}
